  if app == nil then error("not the store of an app", 2) end
  local n = 0
  for _ in pairs(app.instances) do n = n + 1 end
  return n
end

-- The ids unmounted since the last call that are not mounted again.
local function drain_removed(app)
  local out = {}
  for _, id in ipairs(app.removed) do
    if app.instances[id] == nil then out[#out + 1] = id end
  end
  app.removed = {}
  return out
end

local function flush(app)
  local rendered = {}
  for _ = 1, 100 do
    if next(app.dirty) == nil then break end
    local list = {}
    for inst in pairs(app.dirty) do list[#list + 1] = inst end
    table.sort(list, function(a, b) return a.depth < b.depth end)
    for _, inst in ipairs(list) do
      if app.dirty[inst] and app.instances[inst.id] == inst then
        rendered[#rendered + 1] = { inst = inst, tree = render_instance(inst, inst.props) }
      end
      app.dirty[inst] = nil
    end
  end
  if next(app.dirty) ~= nil then
    error("the view keeps changing state while rendering", 0)
  end
  local patches = {}
  for _, r in ipairs(rendered) do
    if app.instances[r.inst.id] == r.inst then
      patches[#patches + 1] = { id = r.inst.id, tree = r.tree }
    end
  end
  local result = { patches = patches, removed = drain_removed(app), changes = app.changes }
  app.changes = {}
  return result
end

-- Creates an app. `spec.view(store, props)` returns the root node;
-- `spec.store` is the initial store, whose changes are mirrored to the
-- Dart LuaStore; `spec.methods` are functions the host can call as
-- `method(store, args)`.
