    next_id = 1, handlers = {}, builders = {}, instances = {}, dirty = {},
    removed = {}, changes = {}, silent = false,
  }
  local store = reactive(raw_store, app, {})
  app.store = store
  app_of[store] = app
  local api = {}

  -- Renders everything; returns { root = node, removed = , changes = }.
  function api.render(props)
    stack = {}
    if app.root then unmount(app.root) end
    app.dirty = {}
    local root = new_instance("root", app, 0)
    root.render = function(p) return view(store, p) end
    app.instances.root = root
    app.root = root
    local node = render_instance(root, props or {})
    local result = { root = { c = "root", n = node }, removed = drain_removed(app), changes = app.changes }
    app.changes = {}
    return result
  end

  -- Renders the root again with new props and returns the patches.
  function api.update(props)
    stack = {}
    app.root.props = props or {}
    app.dirty[app.root] = true
    return flush(app)
  end

  -- Runs event handler `id` with the `n` values of `args`; returns the
  -- patches.
  function api.dispatch(id, args, n)
    stack = {}
    local fn = app.handlers[id]
    if fn ~= nil then fn(unpack(args or {}, 1, n or 0)) end
    return flush(app)
  end

  -- Runs builder `id` (an itemBuilder) with the `n` values of `args`, the
  -- first being the BuildContext placeholder. The output is a component
  -- instance of its own, so state it reads re-renders only this item.
  -- Returns { node = , removed = }, or nil for a builder that is gone.
  function api.build(id, args, n)
    stack = {}
    local builder = app.builders[id]
    if builder == nil then return nil end
    local owner = builder.owner
    if app.instances[owner.id] ~= owner then return nil end
    args = args or {}
    n = n or 0
    local key = {}
    for i = 2, n do key[#key + 1] = tostring(args[i]) end
    local iid = owner.id .. "/$b" .. id .. "/" .. table.concat(key, ",")
    local inst = app.instances[iid]
    if inst == nil then
      inst = new_instance(iid, app, owner.depth + 1)
      inst.owner = owner
      inst.builder = id
      inst.render = function()
        local current = app.builders[id]
        if current == nil then error("the builder of " .. iid .. " is gone", 0) end
        return current.fn(unpack(args, 1, n))
      end
      app.instances[iid] = inst
    end
    owner.children[iid] = inst
    local node = render_instance(inst, {})
    return { node = { c = iid, n = node }, removed = drain_removed(app) }
  end

  -- Unmounts builder output `id` after Flutter disposed it; returns
  -- { removed = }.
  function api.release(id)
    stack = {}
    local inst = app.instances[id]
    if inst ~= nil and inst.owner ~= nil then
      if inst.owner.children[id] == inst then inst.owner.children[id] = nil end
      unmount(inst)
    end
    return { removed = drain_removed(app) }
  end

  -- Runs `methods[name](store, args)`; returns the patches and `value`.
  function api.call(name, args)
    stack = {}
    local fn = methods[name]
    if type(fn) ~= "function" then
      error("the app has no method " .. tostring(name), 2)
    end
