    app.silent = true
    local ok, err = pcall(function()
      local t = store
      for i = 1, #path - 1 do
        if t[path[i]] == nil then t[path[i]] = {} end
        t = t[path[i]]
      end
      t[path[#path]] = value
    end)
    app.silent = false
    if not ok then error(err, 0) end
    return flush(app)
  end

  -- The store as plain data.
  function api.snapshot()
    return raw_store
  end

  return api
end

---------------------------------------------------------------- values
-- Value types build the plain data that the Dart decoders read.

local function strict(type_name, values)
  return setmetatable(values, {
    __index = function(_, key)
      error(type_name .. " has no member " .. tostring(key), 2)
    end,
  })
end

-- An enum whose values are their names: MainAxisAlignment.center == "center".
-- `end` is a Lua keyword: write MainAxisAlignment["end"] or .end_.
function M.enum(type_name, names)
  local values = {}
  for _, name in ipairs(names) do values[name] = name end
  if values["end"] then values.end_ = "end" end
  return strict(type_name, values)
end

local function callable(type_name, call, members)
  local t = members or {}
  return setmetatable(t, {
    __call = function(_, ...) return call(...) end,
    __index = function(_, key)
      error(type_name .. " has no member " .. tostring(key), 2)
    end,
  })
end

local function copy(t)
  local out = {}
  if t then for k, v in pairs(t) do out[k] = raw_of[v] or v end end
  return out
end

local function byte(v) return math.floor(v) % 256 end

local values = {}

values.Color = callable("Color", function(argb) return argb end, {
  fromARGB = function(a, r, g, b)
    return byte(a) * 16777216 + byte(r) * 65536 + byte(g) * 256 + byte(b)
  end,
  fromRGBO = function(r, g, b, opacity)
    return byte(opacity * 255 + 0.5) * 16777216 + byte(r) * 65536 + byte(g) * 256 + byte(b)
  end,
})

values.EdgeInsets = strict("EdgeInsets", {
  zero = 0,
  all = function(value) return value end,
  symmetric = function(t) return { horizontal = t.horizontal, vertical = t.vertical } end,
  only = copy,
  fromLTRB = function(left, top, right, bottom)
    return { left = left, top = top, right = right, bottom = bottom }
  end,
})

values.Radius = strict("Radius", {
  zero = 0,
  circular = function(radius) return radius end,
})

values.BorderRadius = strict("BorderRadius", {
  zero = 0,
  circular = function(radius) return radius end,
  all = function(radius) return radius end,
  only = copy,
})

values.Offset = callable("Offset", function(dx, dy) return { dx = dx, dy = dy } end,
  { zero = { dx = 0, dy = 0 } })

values.Alignment = callable("Alignment", function(x, y) return { x = x, y = y } end)
for _, name in ipairs({
  "topLeft", "topCenter", "topRight", "centerLeft", "center", "centerRight",
  "bottomLeft", "bottomCenter", "bottomRight",
}) do
  rawset(values.Alignment, name, name)
end

values.Border = strict("Border", { all = copy })
values.BoxShadow = copy
values.BoxDecoration = copy
values.TextStyle = copy
values.LinearGradient = copy

values.Duration = function(t)
  t = t or {}
  return (t.days or 0) * 86400000 + (t.hours or 0) * 3600000
    + (t.minutes or 0) * 60000 + (t.seconds or 0) * 1000
    + (t.milliseconds or 0) + (t.microseconds or 0) / 1000
end

values.NetworkImage = function(url) return { network = url } end
values.AssetImage = function(name) return { asset = name } end

-- Icon names; the host registers the icon data for each name.
values.Icons = setmetatable({}, { __index = function(_, name) return name end })

local enums = {
  Axis = { "horizontal", "vertical" },
  BoxFit = { "fill", "contain", "cover", "fitWidth", "fitHeight", "none", "scaleDown" },
  BoxShape = { "rectangle", "circle" },
  CrossAxisAlignment = { "start", "end", "center", "stretch", "baseline" },
  FlexFit = { "tight", "loose" },
  FontStyle = { "normal", "italic" },
  FontWeight = { "normal", "bold", "w100", "w200", "w300", "w400", "w500", "w600", "w700", "w800", "w900" },
  HitTestBehavior = { "deferToChild", "opaque", "translucent" },
  MainAxisAlignment = { "start", "end", "center", "spaceBetween", "spaceAround", "spaceEvenly" },
  MainAxisSize = { "min", "max" },
  StackFit = { "loose", "expand", "passthrough" },
  TextAlign = { "left", "right", "center", "justify", "start", "end" },
  TextDecoration = { "none", "underline", "overline", "lineThrough" },
  TextOverflow = { "clip", "fade", "ellipsis", "visible" },
  WrapAlignment = { "start", "end", "center", "spaceBetween", "spaceAround", "spaceEvenly" },
  WrapCrossAlignment = { "start", "end", "center" },
}
for name, list in pairs(enums) do values[name] = M.enum(name, list) end

M.values = values

---------------------------------------------------------------- core

-- The core library (package:flutter/widgets.dart). A dotted name is a named
-- constructor. Keep in step with coreLibrary() in Dart and ui.d.tl.
local CORE = {
  "Align", "AspectRatio", "Center", "ClipRRect", "ColoredBox", "Column",
  "Container", "DecoratedBox", "DefaultTextStyle", "Expanded", "Flexible",
  "GestureDetector", "Icon", "Image", "Image.asset", "Image.network",
  "ListView", "ListView.builder", "ListView.separated", "Opacity", "Padding",
  "Positioned", "Row", "SafeArea", "SingleChildScrollView", "SizedBox",
  "SizedBox.expand", "SizedBox.shrink", "Spacer", "Stack", "Text", "Wrap",
}

M.core = M.library("core", CORE, {
  Text = { "data" },
  Icon = { "icon" },
  ["Image.network"] = { "src" },
  ["Image.asset"] = { "name" },
})

-- Everything ui.install() makes global.
M.exports = { App = M.app, ui = M }
for name, value in pairs(values) do M.exports[name] = value end
for name, ctor in pairs(M.core) do M.exports[name] = ctor end

-- Copies `exports` (default: M.exports) into `env` (default: _G), so that
-- scripts write `Column { ... }` instead of `ui.core.Column { ... }`.
function M.install(exports, env)
  env = env or _G
  for name, value in pairs(exports or M.exports) do env[name] = value end
  return env
end

return M
